                        "type": "string",
                        "description": "メールアドレスを調べたい人の名前"
                    },
                },
                "required": ["name"]
            }
          }
    },
    {
        "type":"function",
        "function": {
            "name": "auto_message",
            "description": "状況にあったメール文を作成、送信する",
            "parameters": {
                "type": "object",
                "properties": {
                    "address": {
                        "type": "string",
                        "description": "宛先のメールアドレス"
                    },
                    "situation": {
                        "type": "string",
                        "description": "送りたいメールの内容"
                    },
                },
                "required": ["address", "situation"]
            }
          }
    }
]
この時以下の発言に対してJSON形式で使用できる関数およびその引数を"name"及び"properties"にそれぞれ格納して出力してください。また複数関数を順番に実行する必要がある場合は順番がわかるようにまとめてJSONに格納してください。
### 発言
田中さんに遅刻する旨のメールが送信したい。

Answer:
[
    {
        "name": "get_email_address",
        "properties": {
            "name": "田中"
        }
    },
    {
        "name": "auto_message",
        "properties": {
            "address": "ここにはget_email_address関数の結果を使用",
            "situation": "遅刻する旨のメール"
        }
    }
]

ModelAnswer:
以下のJSON形式で、発言に対応する関数と引数を出力します。複数の関数が必要な場合は順番に実行する必要があるため、ステップバイステップで処理を記述します。  

```json
{
  "steps": [
    {
      "function": {
        "name": "get_email_address",
        "parameters": {
          "name": "田中さん"
        }
      }
    },
    {
      "function": {
        "name": "auto_message",
        "parameters": {
          "address": "[取得したメールアドレス]", // 前の関数で取得したメールアドレスを使用
          "situation": "遅刻の旨のメール"
        }
      }
    }
  ]
}
```

### 解説  
1. **`get_email_address` 関数**  
   - 名前「田中さん」からメールアドレスを検索します。  
   - この関数の結果（メールアドレス）が次のステップで使用されます。  

2. **`auto_message` 関数**  
   - 検索したメールアドレスに「遅刻の旨のメール」を送信します。  
   - `address` に取得したメールアドレスを指定し、`situation` に内容を記載します。  

この順序で処理を行うことで、田中さんへの遅刻通知メールを自動送信できます。

